from author import *
c=C('循环、数组与字符串指令')
L(c,'计数循环与CX',('LOOP的动作','先把CX减1；剩余次数非0则跳回'),('给定过程','CX=3；每轮AX加2，最后AX=6、CX=0'),
'用循环重复一个动作，先准备次数，再安排每轮工作。本例让AX从零开始，重复三次加二。CX保存次数，LOOP执行时先让CX减一，剩余次数非零就转回标签，减到零就向下继续。LOOP直接使用CX完成这两步，原有条件标志保持原值。读循环时，可以把初始化、每轮动作和回跳条件分成三块，再把CX的三、二、一、零依次写在旁边。',
'现在从第一轮开始，AX得到二，LOOP把CX从三减到二，继续下一轮。第二轮AX成为四，CX减到一。第三轮AX成为六，CX减到零，执行离开循环。三次加法与三次计数更新一一对应，AX保存累计结果，CX保存当前剩余次数。画面里初始化在回跳目标之前，因此进入下一轮时会接着做加法。按这个结构逐轮列状态，最后还能直接读出总共做了几次。',['LOOP先减CX，再判断非0','LOOP直接递减并检查CX'],['初始化放在循环之外','逐轮写数值与CX'],code='xor ax, ax\nmov cx, 3\nagain: add ax, 2\nloop again',run='count_loop',output=['AX依次为2、4、6；最终CX=0'],lines=[[1,2],[3]],visual=V('execution',trace='count_loop',windows=[[2,2],[2,8]],regs=['ax','cx','ip']),anchors=[None,'现在从第一轮开始'],hints=[[],[('LOOP把CX从三减到二',[4])]])
L(c,'零次循环与入口保护',('边界问题','循环体先执行且CX初始为0，LOOP会减成FFFFh'),('常用保护','若允许长度为0，可在循环体前用JCXZ跳过'),
'长度为零时，先决定循环是否进入。若代码直接进入循环体，随后执行LOOP，CX的零会减成FFFF，接着继续回跳；这样的结构会执行六万五千五百三十六轮。原因是CX只有十六位，零减一后按该位宽回绕。我们希望长度为零时直接到结束位置，就在循环体入口安排一次检查。把入口检查与循环末尾的计数分开，零次执行也就有了明确路径。',
'现在在循环体前增加JCXZ，CX为零时转到DONE，AX保持初始零。JCXZ直接读取CX；正数长度则顺序进入循环体，再由LOOP逐轮递减。检查这样的程序，可以分别代入零、一、三：零次直接结束，一次执行后退出，三次则走完三轮。这三种输入覆盖了入口、第一次退出和多轮回跳，循环结构怎样控制次数也就完整地呈现出来。',['先执行的LOOP结构要检查CX=0','零初始计数会回绕到FFFFh'],['JCXZ直接检查CX','长度为0应有明确路径'],code='xor ax, ax\nmov cx, 0\njcxz done\nagain: add ax, 2\nloop again\ndone: nop',run='zero_loop_guard',output=['CX=0时跳过循环；AX=0'],lines=[[1,2],[3]],visual=V('execution',trace='zero_loop_guard',windows=[[2,2],[2,4]],regs=['ax','cx','ip']),anchors=[None,'现在在循环体前增加JCXZ'])
L(c,'字节数组与逐项求和',('给定布局','0200h起的3个字节为3、5、7；SI保存当前偏移'),('三个角色','SI定位，CX计数，累加寄存器保存当前总和'),
'把三、五、七三个字节连续放在内存中，就得到一个小数组，起点是零二零零。SI保存当前地址偏移，CX保存剩余项数，AX保存总和。每轮从SI指向的位置读一个字节，参加累加，再把SI加一。可以先画三个内存格，给它们写上地址零二零零、零二零一、零二零二，再把SI画成指向当前格子的箭头。数组的顺序读取就有了具体位置。',
'现在依次读取三、五、七。每次先把字节放进BL，并把BH清零，再用整个BX加到AX，三这个字节就以十六位的三参加累加。每处理一项，SI前进一，CX递减一。最后总和十五，SI到零二零三，CX为零。总和、地址和次数是三条同时推进的线：总和反映已处理的数据，SI指向下一项，CX表示剩余工作。用这三项状态一起检查，就能确认循环的处理范围。',['SI、CX和总和分别承担任务','字节数组每次偏移加1'],['清BH后再把BX作为无符号字相加','循环次数必须与数组长度匹配'],code='mov si, 0200h\nmov cx, 3\nxor ax, ax\nagain: mov bl, [si]\nxor bh, bh\nadd ax, bx\ninc si\nloop again',run='byte_array_sum',output=['AX=15；SI=0203h；CX=0'],lines=[[1,2,3],[4,5]],visual=V('execution',trace='byte_array_sum',windows=[[3,3],[3,18]],regs=['ax','bx','si','cx'],memory=[0x200,0x201,0x202]),anchors=[None,'现在依次读取三、五、七'])
L(c,'字数组与下标步长',('元素宽度','一个字占2字节，下一个元素的起点偏移应加2'),('宽度与范围','累加和用16位保存时，仍需检查是否超过65535'),
'数组元素改成十六位的字，每项占两个字节。第一项从零二零零开始，第二项从零二零二开始，第三项从零二零四开始，因此访问完一项，地址偏移应前进二。先在内存图上用框标出每个字的两个字节，再把箭头从一个框移到下一个框。元素大小决定了步长，元素个数决定循环次数，这两项分别安排到指针更新与计数逻辑里。',
'现在让指针每轮前进二，依次把一百、二百、三百累加，得到六百。最后SI停在零二零六，CX回到零。读取一个字时，处理器把低地址的低字节与后一字节组合起来，按照小端顺序交给加法。选择累加位宽时，可以先算最大可能总和，再确定保存范围。读字数组的题，也可以分栏写元素序号、起始偏移和数值，随每一轮一起更新。',['字数组每项占2字节','偏移步长与元素大小一致'],['处理器按小端读取一个字','按最大总和选择累加位宽'],code='mov si, 0200h\nmov cx, 3\nxor ax, ax\nagain: add ax, [si]\nadd si, 2\nloop again',run='word_array_sum',output=['AX=600；SI=0206h；CX=0'],lines=[[1,2],[4]],visual=V('execution',trace='word_array_sum',windows=[[3,3],[3,12]],regs=['ax','si','cx'],memory=[0x200,0x201,0x202,0x203,0x204,0x205]),anchors=[None,'现在让指针每轮前进二'])
L(c,'字符串传送与方向标志',('MOVSB规则','从DS:SI复制1字节到ES:DI；地址按DF方向自动更新'),('REP规则','结合CX重复；CLD置DF=0，让SI和DI向高地址递增'),
'MOVSB适合复制一段连续字节。它从DS与SI指定的位置读一个字节，写到ES与DI指定的位置，随后按方向标志DF更新两个偏移。CLD把DF置零，让两个地址向高处递增。先把源和目标画成两排格子，分别给SI与DI标箭头，就能同时看见读取位置和写入位置。这里源是ABC三个字节，目标从零三零零开始，复制次数由CX给出。',
'现在明确设置方向、源地址、目标地址与三个字节的数量，再用REP MOVSB复制。REP让这条传送随CX重复，完成后，目标区得到ABC三个字符，SI到零二零三，DI到零三零三，CX为零。本例DS与ES已设为同一段，所以两个偏移可以直接对照。分析一段字节复制时，把源段、目标段、长度和方向写成四项，随后沿着两个地址箭头逐项检查。',['源使用DS:SI，目标使用ES:DI','DF决定递增还是递减'],['REP按CX重复；长度明确给出','段、长度、方向与空间都要明确'],code='cld\nmov si, 0200h\nmov di, 0300h\nmov cx, 3\nrep movsb',run='string_copy',output=['目标0300h起为ABC；SI=0203h，DI=0303h，CX=0'],lines=[[1],[2,3,4]],visual=V('execution',trace='string_copy',windows=[[1,1],[4,8]],regs=['si','di','cx'],memory=[0x200,0x201,0x202,0x300,0x301,0x302]),anchors=[None,'现在明确设置方向、源地址、目标地址与三个字节的数量'],hints=[[],[('再用REP MOVSB复制',[5])]])
Q(c,'循环与元素宽度',('给定','3个16位元素，起点0200h，按元素访问后前进'),('问题','每轮地址加多少；3轮后偏移多少；长度0如何避免误入LOOP'),
'数组从偏移零二零零开始，共有三个十六位元素，处理完一项就前进到下一项。请写出每轮地址增加多少，三轮以后的偏移，以及长度为零时可以在循环体前使用的入口检查指令。先给每个元素框出两个字节，再沿框之间的位置计算，接下来留四秒思考。',
'一个元素占两个字节，每轮地址加二，三轮后SI成为零二零六。这个位置是数组末尾之后，表示三个元素都已处理完。长度为零时，在循环体前用JCXZ转到结束位置，直接完成零次路径。把步长、次数和入口检查分别写出，就能同时说明数组布局与循环控制。',('步长与终态','每轮+2；最终SI=0206h'),('零长度保护','CX=0时由JCXZ直接到done'))

c=C('栈与子程序')
L(c,'栈顶与压栈出栈',('本课字操作','PUSH先让SP减2，再写SS:SP；POP先读，再让SP加2'),('先入后出','最后压入的字先取出；SP标记当前栈顶'),
'栈按后放入、先取出的顺序保存数据。八零八六的字压栈先让SP减二，再把一个字写入SS与SP指定的位置；字出栈先读栈顶，再让SP加二。我们在图上按地址编号表示方向，SP减小对应向较低偏移增长。这里已经准备好有效栈区，可以专心追踪每个字的存放位置。画一次PUSH或POP时，同时记录值和SP，取放顺序就能对应起来。',
'现在从SP等于零一零零开始，压入AX中的一二三四，SP到零零FE；再压入BX中的ABCD，SP到零零FC。第一次POP给DX取得ABCD，第二次给CX取得一二三四，SP回到零一零零。原内存字节通常继续保留，SP标记当前有效栈顶的位置。把两次减二和两次加二连成一条轨迹，再按后入先出分配数值，就能同时检查栈顺序与指针终态。',['字PUSH先减SP再写，POP先读再加','SS与SP共同决定栈位置'],['后压入先弹出','POP移动SP，原字节通常保留'],code='mov sp, 0100h\nmov ax, 1234h\nmov bx, 0ABCDh\npush ax\npush bx\npop dx\npop cx',run='push_pop',output=['DX=ABCDh；CX=1234h；SP回到0100h'],lines=[[1,2,3],[4]],visual=V('execution',trace='push_pop',windows=[[3,3],[3,7]],regs=['sp','dx','cx'],memory=[0xfc,0xfd,0xfe,0xff]),anchors=[None,'现在从SP等于零一零零开始'],hints=[[],[('再压入BX中的ABCD',[5]),('第一次POP给DX取得ABCD',[6]),('第二次给CX取得一二三四',[7])]])
L(c,'近调用与返回地址',('近CALL','把下一条指令的IP压栈，再跳到本段子程序'),('近RET','从栈顶恢复IP，返回值与保护项另按约定处理'),
'子程序把一段可重复使用的步骤集中到一个位置。调用者用CALL进入，子程序用RET回到调用之后。本页使用同一代码段内的近调用：CALL把下一条指令的IP压栈，再跳到目标。这样栈里就保存了一条回程地址。把调用位置、子程序入口和回程位置画成三个点，沿CALL和RET连起来，就能看到一次调用怎样回到原来的执行流程。',
'现在从AX等于四出发，CALL进入加一子程序，AX变成五，RET再回到调用之后，把结果复制到BX。最终AX与BX都保存五。近CALL压入一个返回IP，SP减二，近RET取回它，SP加二。子程序完成计算，返回地址负责接续控制流程，两者各有保存位置。读调用题时，一边追踪数值的输入和输出，一边追踪栈里的返回位置，过程就完整了。',['近CALL保存下一条指令IP','CALL保存返回IP；JMP直接转移位置'],['本页限定同段近CALL与RET','RET恢复控制位置；寄存器按约定恢复'],code='mov ax, 4\ncall plus_one\nmov bx, ax\njmp done\nplus_one: inc ax\nret\ndone: nop',run='near_call',output=['AX=5；BX=5；近CALL/RET后SP恢复'],lines=[[1],[2]],visual=V('execution',trace='near_call',windows=[[1,1],[1,7]],regs=['ax','bx','sp','ip']),anchors=[None,'现在从AX等于四出发'],hints=[[],[('CALL进入加一子程序',[2]),('AX变成五',[5]),('RET再回到调用之后',[6]),('把结果复制到BX',[3])]])
L(c,'参数、返回值与寄存器保护',('约定示例','AX传入并返回数值；BX由子程序保存和恢复'),('实现办法','使用BX前PUSH BX；返回前POP BX，并保持栈平衡'),
'给子程序安排一份清楚的合作约定：AX提供输入，计算后的AX提供返回值，BX由子程序负责保持。调用者就知道从哪里交数据、到哪里取结果，以及哪些原值可以继续使用。本例把AX里的四加上三，返回七。BX原先保存九十九，子程序会暂时借用它，所以先保存原值，结束前再恢复。参数、结果和保护集合写清楚，几个代码段就能配合完成任务。',
'现在让子程序先保存BX，临时把三放进去完成加法，AX得到七，最后把BX恢复为原来的九十九，再执行RET。栈里从上到下放着当前保存项和返回地址，恢复完保存项以后，返回地址重新位于栈顶。检查这次调用，可以读三项结果：AX等于七，BX等于九十九，SP回到调用前的位置。这三项分别核对计算、寄存器保护和栈上的取放是否配对。',['参数、结果和保护集合要约定','本例约定AX传入返回，BX由子程序保护'],['临时改BX前保存，结束后恢复','按保存顺序恢复，让返回IP回到栈顶'],code='mov ax, 4\nmov bx, 99\ncall add_three\njmp done\nadd_three: push bx\nmov bx, 3\nadd ax, bx\npop bx\nret\ndone: nop',run='save_register',output=['AX=7；BX仍为99；SP恢复'],lines=[[1,2],[5]],visual=V('execution',trace='save_register',windows=[[2,2],[3,10]],regs=['ax','bx','sp']),anchors=[None,'现在让子程序先保存BX'],hints=[[],[('临时把三放进去完成加法',[6,7]),('最后把BX恢复',[8])]])
L(c,'用BP访问栈参数',('近调用布局','保存旧BP后，[BP+2]是返回IP，[BP+4]可读第一个字参数'),('约定范围','本例参数由调用者清理；BP普通寻址默认SS'),
'参数也可以通过栈传递。调用者先压入一个字，近CALL再压返回IP，子程序又保存旧BP，随后让BP对齐当前栈顶。按这个顺序，从BP向高偏移看，零偏移处是旧BP，偏移二是返回IP，偏移四就是第一个字参数。偏移量来自眼前这份布局。先把三个字按入栈顺序画好，再标BP加二、BP加四，就能直接找到要读取的数据。',
'现在沿栈布局读出参数七，再加一，AX得到八。子程序先恢复BP，再RET，调用者随后把参数占用的两个字节清理掉，SP回到原位。含BP的普通寻址默认使用SS，所以本例通过BP读取栈中的参数。这里采用调用者清理参数的约定，双方各自完成对应步骤。以后遇到多个参数，可以继续按实际保存顺序增加格子，再计算各项相对BP的位置。',['偏移来自实际入栈布局','本例近调用，保存一个旧BP'],['BP普通寻址默认SS','本例由调用者清理参数'],code='mov ax, 7\npush ax\ncall add_one\nadd sp, 2\njmp done\nadd_one: push bp\nmov bp, sp\nmov ax, [bp+4]\ninc ax\npop bp\nret\ndone: nop',run='stack_argument',output=['AX=8；调用者清理参数后SP恢复'],lines=[[1,2,3],[8]],visual=V('execution',trace='stack_argument',windows=[[3,3],[5,12]],regs=['ax','bp','sp','ip']),anchors=[None,'现在沿栈布局读出参数七'],hints=[[],[('再加一',[9]),('子程序先恢复BP',[10]),('再RET',[11]),('调用者随后把参数占用的两个字节清理掉',[4])]])
L(c,'栈平衡与返回错误',('常见错误','多PUSH一个字，却直接RET；临时值会被当作返回地址'),('排查顺序','逐项列入栈与出栈；核对当前SP顶端究竟是谁'),
'看一个具体的栈布局问题。近CALL已经把返回IP压在栈顶，子程序随后又压入一个临时字。此时栈顶属于临时字，执行RET就会把它取作返回位置，控制流程因而转到这个临时数值对应的偏移。原因集中在两次取放之间：当前SP顶端保存的是谁，RET就读取谁。把返回地址与临时字分开画出来，错误路径的来源就能直接找到。',
'现在把正确的压栈、恢复、返回放在图上。先保存需要借用的寄存器，完成工作后按对应顺序恢复，让真正的返回IP回到栈顶，最后执行RET。每压入一个字，在表里增加一项；每弹出一个字，就把顶端项取走。分析子程序时，用这张表配合SP的变化，再检查返回值与保护寄存器，代码怎样离开函数就有了明确依据。',['RET按当前栈顶取返回位置','当前栈顶的临时字会被RET取作返回位置'],['修复要让真正返回地址回到栈顶','同时检查结果、保护项和SP'],visual=V('stack_contract'),anchors=[None,'现在把正确的压栈、恢复、返回放在图上'])
Q(c,'入栈顺序与恢复',('过程','SP=0100h；PUSH AX；PUSH BX；POP DX；POP CX'),('给定','AX=1234h，BX=ABCDh；栈区有效且无其他栈操作'),
'给定有效栈区，SP从零一零零开始，AX是一二三四，BX是ABCD。程序依次PUSH AX、PUSH BX、POP DX、POP CX。请写出DX、CX和最终SP。可以先画出两次压栈留下的字，再按后放入先取出的顺序处理，接下来留四秒思考。',
'DX取得最后压入的ABCD，CX接着取得一二三四。两次字压栈让SP依次减二，两次字出栈再依次加二，最后回到零一零零。数值按后入先出排列，指针按每次两个字节计算。若继续分析包含CALL的过程，就把返回IP也作为一个字加入同一张栈表。',('弹出结果','DX=ABCDh；CX=1234h'),('栈指针','0100h → 00FEh → 00FCh → 00FEh → 0100h'))

c=C('字符处理与输入输出')
L(c,'数字与ASCII字符',('两种表示','数值5是05h；字符“5”的ASCII码是35h'),('限定转换','已确认是0～9的数字时，加或减字符0可转换'),
'数值五保存为一个字节时是零五H，字符五的ASCII编码则是三五H。我们在程序里计算数量时使用数值，显示数字时需要相应字符编码。单个十进制数字零到九的ASCII码连续排列，从三零H到三九H。因此，在已知数字范围内，加字符零可以把数值变成字符；读取数字字符后，减字符零可以还原数量。先分清当前数据的含义，转换步骤就有了方向。',
'现在把已知数值五加上字符零的编码，就得到字符五，AL保存三五H。反过来，确认输入是零到九的数字字符后，减字符零得到相应数值，本例BL回到零五H。可以把两种形式画在一条线上：左边是参与计算的数值，右边是用来显示的字符码。一个数字字符完成一次这样的转换，多位整数则逐位拆开处理，后面会用除十和栈完成这个任务。',['数值与字符编码分开','先转换数值，再按字符接口输出'],['只对已确认的单个数字使用此转换','多位数字需要另一套步骤'],code="mov al, 5\nadd al, '0'\nmov bl, al\nsub bl, '0'",run='ascii_digit',output=['AL=35h（字符5）；BL=05h（数值5）'],lines=[[1],[2]],visual=V('execution',trace='ascii_digit',windows=[[1,1],[1,4]],regs=['al','bl']),anchors=[None,'现在把已知数值五加上字符零的编码'],hints=[[],[('减字符零得到相应数值',[4])]])
L(c,'DOS字符输出与环境约定',('明确环境','本章使用DOS INT 21h接口；AH选择服务'),('单字符输出','AH=02h，DL放字符码，再INT 21h'),
'这一章用传统DOS的INT二一H服务完成字符输入输出。AH选择服务，单字符输出用零二H，DL保存要显示的字符编码。处理器执行指令，运行环境按接口约定完成字符输出。工程用一个明确的教学服务适配器记录这些调用，便于自动检查输出内容。读接口代码时，先查看服务号，再找到输入寄存器，最后把请求和返回结果对应起来。',
'现在把字符A放到DL，把零二H放到AH，再请求这项DOS服务，输出记录得到A。三个步骤分别准备数据、选择功能、提交请求。把DL换成字符五的ASCII码，同一项服务就会显示五。字符输出接收的是编码，所以前面的数值转字符步骤可以直接接到这里。接下来输出字符串时，我们会改用另一项服务，让地址与结束标记共同描述整段文字。',['INT 21h服务依赖DOS环境','AH服务号与DL字符码分别准备'],['工程用明确的教学接口适配器验证','本例使用DOS INT 21h服务'],code="mov dl, 'A'\nmov ah, 02h\nint 21h",run='dos_character',output=['教学DOS服务记录输出：A'],lines=[[1,2],[1]],visual=V('execution',trace='dos_character',windows=[[2,2],[0,3]],regs=['ah','dl']),anchors=[None,'现在把字符A放到DL'],hints=[[],[('把零二H放到AH',[2]),('再请求这项DOS服务',[3])]])
L(c,'字符串输出与结束标记',('DOS 09h服务','DS:DX指向开头；以$为结束标记'),('别混用协议','以0结尾与以$结尾是两种不同约定'),
'DOS的零九H服务从DS与DX给出的地址开始读取字符，以美元符号作为结束标记。我们准备H、I、美元符号三个字节，DX指向第一个H。服务依次读取字符，读到结束标记时完成本次输出，所以屏幕内容是HI。地址描述开头，结束标记描述终点，这两项共同定义了本次要处理的范围。把内存中的字节按顺序画出来，整个读取过程就很直观。',
'现在从偏移零二零零开始读取，依次送出H和I，到美元符号处结束。DS给出数据段，DX给出开头的偏移，服务内部逐字节处理这段内容。字符串接口常见三种约定：按长度、以零结束、以特定字符结束。我们这次使用的是第三种。拿到一项具体服务，先按它的约定准备开头和范围，再查看实际输出，就能把内存布局与接口行为对应起来。',['09h按DS:DX找到开头','美元符号是这项服务的结束标记'],['0结束与$结束分别按接口约定准备','地址正确还要协议正确'],code='mov dx, 0200h\nmov ah, 09h\nint 21h',run='dos_string',output=['0200h起为HI$；服务记录输出HI'],lines=[[1,2],[3]],visual=V('execution',trace='dos_string',windows=[[2,2],[2,3]],regs=['ds','dx','ah'],memory=[0x200,0x201,0x202]),anchors=[None,'现在从偏移零二零零开始读取'])
L(c,'读取字符与输入验证',('DOS 01h服务','读取并回显一个字符，字符码返回AL'),('转换之前','先检查字符是否在“0”到“9”，合法后减“0”'),
'DOS的零一H服务读取并回显一个字符，把字符码放到AL。本例键入七，AL取得三七H，输出记录也出现字符七。接下来要把它用于数字计算，就先检查是否属于零到九的字符范围。可以把这一步理解为给输入分类：范围内的字符进入转换路径，其他字符进入另一条处理路径。输入、分类与转换分开安排，每个步骤都有明确的结果。',
'现在先拿输入与字符零、字符九比较，范围通过后减字符零，得到数值七，再保存到BL。若输入A，比较会转到BAD，把BL写成FF，表示本例选择的非法输入标记。两条路径最终在DONE汇合，调用者可以根据结果继续处理。这个程序完成单个数字字符的读取与转换；处理多位数时，可以把每次取得的合法数字，加入前面已经形成的十进制数值。',['返回AL的是字符码','读取后先验证0～9字符范围'],['先检查0～9，再减字符0','本例只处理单个数字字符'],code="mov ah, 01h\nint 21h\ncmp al, '0'\njb bad\ncmp al, '9'\nja bad\nsub al, '0'\nmov bl, al\njmp done\nbad: mov bl, 0FFh\ndone: nop",run='dos_input',output=['给定输入7：回显7；BL=7；输入A时BL=FFh'],lines=[[1,2],[3,4]],visual=V('execution',trace='dos_input',windows=[[2,2],[2,10]],regs=['al','bl'],flags=['cf','zf']),anchors=[None,'现在先拿输入与字符零、字符九比较'],hints=[[],[('范围通过后减字符零',[7])]])
L(c,'多位整数转十进制字符',('拆位','无符号整数反复除10，余数先得到个位，再得到十位、百位'),('输出顺序','余数可先压栈，再反序弹出；0需要明确处理'),
'把一百二十三转成十进制字符，可以反复除十。第一次商十二、余数三，取得个位；第二次用十二除十，商一、余数二，取得十位；第三次商零、余数一，取得百位。于是余数按三、二、一的顺序出现，显示时则需要一、二、三。把每次商和余数分两栏写下，就能同时看见拆位过程，以及接下来需要反转的输出顺序。',
'现在把余数依次压栈，三先入栈，二随后，一最后位于栈顶。弹出时取得一、二、三，各自加字符零，再交给单字符服务输出，就得到一百二十三。使用十六位除数时，每轮先清DX，让当前AX作为完整无符号被除数。输入零时，也执行一次除十，取得余数零，随后显示字符零。这段步骤可以封装成子程序，接收一个数值，统一完成拆位、反序和字符输出。',['除10得到商与余数','余数顺序与显示顺序相反'],['每轮16位DIV前清DX','原数0要输出一个字符0'],visual=V('decimal_conversion'),anchors=[None,'现在把余数依次压栈'])
Q(c,'字符与字符串接口',('给定','AL保存数值7；内存有字符HI与一个$结束标记'),('问题','单字符7的编码转换；DOS 09h的实际输出内容'),
'AL保存数值七，准备通过单字符方式显示。请写出把它转成字符编码的操作。另有一段按DOS零九H约定准备的HI加美元符号字符串，请写出它的实际显示内容。分别从数据编码和服务的结束规则来判断，接下来留四秒思考。',
'数值七加字符零的编码，得到字符七，再按单字符接口要求把它放到DL。零九H字符串服务则从开头输出H和I，在美元符号处结束，显示内容是HI。前一问处理数值到字符的转换，后一问处理字符序列的读取范围，把它们各自对应到数据和接口约定，就能写出完整答案。',('单字符','7 + ASCII“0” → ASCII“7”，再按接口放入DL'),('09h字符串','输出HI，到$处结束'))
